# frozen_string_literal: true

module PermissionForge
  # Level 3 — Postgres Row-Level Security runtime plumbing.
  #
  # Policies are generated by {Services::RlsPolicyGenerator} and installed via
  # `rails generate permission_forge:rls` (initial migration) or
  # `rake permission_forge:rls:sync` (after rule edits). This module executes
  # that DDL and manages the per-request session variable the policies read.
  #
  # Setting the user:
  #
  #   # Block form — transaction-scoped (SET LOCAL), ideal for jobs/services:
  #   PermissionForge::RLS.with_user(user) { Customer.where(...) }
  #
  #   # Controller form — session-scoped, cleared in ensure:
  #   around_action do |_controller, action|
  #     PermissionForge::RLS.set_user!(current_user)
  #     action.call
  #   ensure
  #     PermissionForge::RLS.clear_user!
  #   end
  #
  # Enforcement caveats (documented in docs/query-scoping.md): a superuser or
  # BYPASSRLS role bypasses policies entirely — the app must connect as a
  # regular role. Under RLS a denied row is invisible, so find_by reports
  # missing (nil / RecordNotFound) rather than NotAuthorizedError.
  #
  # @api public
  module RLS
    module_function

    def postgres?
      with_connection { |connection| connection.adapter_name.match?(/postgresql/i) }
    rescue ActiveRecord::NoDatabaseError, ActiveRecord::ConnectionNotEstablished
      false
    end

    def ensure_postgres!
      return if postgres?

      raise PermissionForge::ConfigurationError,
            I18n.t('permission_forge.errors.rls_requires_postgres',
                   default: 'PermissionForge RLS requires PostgreSQL — the current database ' \
                            'adapter does not support row-level security policies.')
    end

    # Runs the block with the RLS session variable set transaction-locally
    # (set_config(..., true) — automatically cleared when the transaction
    # ends, so no reset bookkeeping and no leakage across pooled connections).
    #
    # The block runs on the connection the variable is set on: one the
    # calling thread already holds, or one taken for the block and given
    # back to the pool after it.
    def with_user(user_or_id)
      ensure_postgres!
      with_connection do |connection|
        connection.transaction do
          apply_user(user_or_id, local: true, connection: connection)
          yield
        end
      end
    end

    # Session-scoped variant for around_action use. MUST be paired with
    # clear_user! in an ensure block — the setting survives on the pooled
    # connection otherwise. Set on the connection the calling thread keeps
    # (leased to it until the request ends), so the request's queries see it.
    def set_user!(user_or_id)
      ensure_postgres!
      apply_user(user_or_id, local: false)
    end

    # Clears the database session variable that carries the current user (PostgreSQL only).
    # @return [void]
    def clear_user!
      return unless postgres?

      run_set_config('', local: false)
    end

    # Generates and executes RLS DDL for every protected model (enable/force +
    # four policies + digest comment), one transaction per table.
    #
    # @return [Array<Hash>] per-table { table:, digest:, skipped_rules: }
    def sync!
      ensure_postgres!
      protected_model_classes.map do |model_class|
        result = Services::RlsPolicyGenerator.call(model_class: model_class)
        with_connection { |connection| execute_in_transaction(connection, result[:statements]) }
        log_skipped_rules(result)
        result.slice(:table, :digest, :skipped_rules)
      end
    end

    # Drops PermissionForge policies and disables RLS on every protected table
    # (used by the generated migration's `down`).
    #
    # @return [Array<String>] the table names cleaned up
    def remove!
      ensure_postgres!
      protected_model_classes.map do |model_class|
        with_connection { |connection| drop_policies(connection, model_class.table_name) }
        model_class.table_name
      end
    end

    # Compares each protected table's live policy digest with the digest the
    # current rule state would produce. A missing policy reports out-of-sync
    # (stored: nil) — enabling Level 3 without installing policies is itself
    # a misconfiguration worth surfacing.
    #
    # @return [Array<Hash>] { table:, expected:, stored:, in_sync: }
    def drift_report
      protected_model_classes.map do |model_class|
        expected = Services::RlsPolicyGenerator.new(model_class: model_class).digest
        stored = stored_digest(model_class.table_name)
        { table: model_class.table_name, expected: expected, stored: stored, in_sync: expected == stored }
      end
    end

    # @param table_name [String]
    # @return [String, nil] the digest of the policy installed on the table
    # @api private
    def stored_digest(table_name)
      row = with_connection do |connection|
        connection.select_value(<<~SQL)
          SELECT d.description
          FROM pg_policy pol
          JOIN pg_class c ON c.oid = pol.polrelid
          JOIN pg_description d ON d.objoid = pol.oid
          WHERE c.relname = #{connection.quote(table_name)}
            AND pol.polname = #{connection.quote(Services::RlsPolicyGenerator::POLICY_NAMES[:select])}
        SQL
      end
      row&.delete_prefix(Services::RlsPolicyGenerator::DIGEST_COMMENT_PREFIX)
    end

    # @return [Array<Class>] the models that include PermissionScopedFindable
    # @api private
    def protected_model_classes
      Concerns::PermissionScopedFindable.protected_model_names.filter_map(&:safe_constantize)
    end

    # A connection for one unit of work: the one the calling thread holds,
    # else one from the pool that goes back to it when the block ends.
    # (`ActiveRecord::Base.connection` is soft-deprecated from Rails 7.2 and
    # would keep a connection leased to the thread.)
    def with_connection(&)
      ActiveRecord::Base.connection_pool.with_connection(&)
    end

    # The connection the calling thread keeps until it is released (the end
    # of the request, or of the job): where a session-scoped setting has to
    # live. `lease_connection` from Rails 7.2; on 7.1 that is `connection`.
    def leased_connection
      pool = ActiveRecord::Base.connection_pool
      pool.respond_to?(:lease_connection) ? pool.lease_connection : pool.connection
    end

    def execute_in_transaction(connection, statements)
      connection.transaction do
        statements.each { |statement| connection.execute(statement) }
      end
    end

    def drop_policies(connection, table_name)
      table = connection.quote_table_name(table_name)
      connection.transaction do
        Services::RlsPolicyGenerator::POLICY_NAMES.each_value do |name|
          connection.execute("DROP POLICY IF EXISTS #{name} ON #{table}")
        end
        connection.execute("ALTER TABLE #{table} NO FORCE ROW LEVEL SECURITY")
        connection.execute("ALTER TABLE #{table} DISABLE ROW LEVEL SECURITY")
      end
    end

    # `connection` defaults to the one the calling thread keeps (set_user!).
    def apply_user(user_or_id, local:, connection: leased_connection)
      id = user_or_id.respond_to?(:id) ? user_or_id.id : user_or_id
      run_set_config(id.to_s, local: local, connection: connection)
    end

    # set_config avoids interpolating the setting name as an identifier —
    # both the name and value travel as quoted literals.
    def run_set_config(value, local:, connection: leased_connection)
      var = PermissionForge.configuration.rls_session_variable
      connection.execute(
        "SELECT set_config(#{connection.quote(var)}, #{connection.quote(value)}, #{local})"
      )
    end

    # Logs the rules a policy sync left out because they cannot be expressed in SQL.
    # @param result [Hash] the sync result
    # @api private
    def log_skipped_rules(result)
      return if result[:skipped_rules].empty?

      Rails.logger&.warn(
        "[PermissionForge] RLS sync for '#{result[:table]}' skipped " \
        "#{result[:skipped_rules].size} untranslatable rule(s) " \
        "(#{result[:skipped_rules].map { |r| "#{r[:rule]}: #{r[:reason]}" }.join(', ')}) — " \
        'join-type rules, dotted field names and rules on an STI subclass resource are enforced at the application layer only.'
      )
    end

    private_class_method :with_connection, :leased_connection, :execute_in_transaction, :drop_policies
  end
end
